import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64
PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.extern .shared .align 16 .b8 dyn_smem[];
// Cooperative tiled transposed 3D convolution (specialized for k=3,
// stride=1, padding=0, groups=1, cubic volumes).
// Each CTA computes one 8x8x8 output tile for eight consecutive output
// channels of one batch element. Every thread computes two adjacent W
// outputs and eight output channels (output-channel register blocking),
// reusing each staged weight vector and each 10x10x10 padded input halo.
// Out-of-bounds halo slots are zero-filled before the input-channel loop.
.visible .entry conv_transpose3d_fwd(
    .param .u64 _in_ptr,
    .param .u64 _w_ptr,
    .param .u64 _out_ptr,
    .param .u32 _total,
    .param .u32 _ic,
    .param .u32 _oc,
    .param .u32 _inD,
    .param .u32 _outD,
    .param .u32 _k
)
{
    .reg .pred  %p<8>;
    .reg .b32   %r<64>;
    .reg .b64   %rd<8>;
    .reg .f32   %f<32>;
    ld.param.u64 %rd0, [_in_ptr];
    ld.param.u64 %rd1, [_w_ptr];
    ld.param.u64 %rd2, [_out_ptr];
    ld.param.u32 %r8,  [_ic];
    ld.param.u32 %r9,  [_oc];
    ld.param.u32 %r10, [_inD];
    ld.param.u32 %r11, [_outD];
    // tile counts: TW = TH = TD = ceil(outD/8)
    add.u32 %r2, %r11, 7;
    shr.u32 %r2, %r2, 3;
    mov.u32 %r5, %r2;
    shr.u32 %r49, %r9, 3;               // OCB = OC/8 output-channel blocks
    // decode ctaid -> (n, ocb, td, th, tw), tw fastest
    mov.u32 %r1, %ctaid.x;
    rem.u32 %r3, %r1, %r2;
    div.u32 %r4, %r1, %r2;
    rem.u32 %r6, %r4, %r5;
    div.u32 %r4, %r4, %r5;
    rem.u32 %r7, %r4, %r5;
    div.u32 %r4, %r4, %r5;
    rem.u32 %r30, %r4, %r49;            // oc block index
    div.u32 %r31, %r4, %r49;            // n
    shl.b32 %r30, %r30, 3;              // oc0 = oc block * 8
    shl.b32 %r13, %r7, 3;               // base_d = td*8
    shl.b32 %r14, %r6, 3;               // base_h = th*8
    shl.b32 %r15, %r3, 3;               // base_w = tw*8
    // thread -> two adjacent W outputs inside the 8x8x8 tile
    mov.u32 %r16, %tid.x;
    and.b32 %r17, %r16, 3;              // w pair = tid % 4
    shr.u32 %r18, %r16, 2;
    and.b32 %r18, %r18, 1;              // low h bit
    shr.u32 %r19, %r16, 3;
    and.b32 %r19, %r19, 7;              // d_l = (tid/8) % 8
    shr.u32 %r33, %r16, 5;
    and.b32 %r33, %r33, 6;              // high h bits
    or.b32 %r18, %r18, %r33;            // h_l in [0,7]
    add.u32 %r36, %r13, %r19;           // od
    add.u32 %r37, %r14, %r18;           // oh
    add.u32 %r38, %r15, %r17;
    add.u32 %r38, %r38, %r17;           // first ow = base_w + 2*w_pair
    mul.lo.u32 %r28, %r10, %r10;        // inD^2
    mul.lo.u32 %r29, %r28, %r10;        // inD^3
    mul.lo.u32 %r44, %r11, %r11;        // outD^2
    // input channel base byte pointer for ic = 0: in + n*IC*inD^3*4
    mul.lo.u32 %r40, %r31, %r8;
    mul.wide.u32 %rd5, %r40, %r29;
    shl.b64 %rd5, %rd5, 2;
    add.u64 %rd3, %rd0, %rd5;           // cur input base ptr
    mul.wide.u32 %rd6, %r29, 4;         // per-ic byte increment
    // weight base byte pointer for ic = 0: w + oc0*27*4
    mul.wide.u32 %rd5, %r30, 108;
    add.u64 %rd4, %rd1, %rd5;           // cur weight base ptr
    mul.wide.u32 %rd7, %r9, 108;        // per-ic byte increment (OC*27*4)
    // shared memory base
    mov.u32 %r32, dyn_smem;
    // per-thread smem read base: (d_l*120 + h_l*12 + 2*w_pair)*4
    mul.lo.u32 %r33, %r19, 120;
    mad.lo.u32 %r33, %r18, 12, %r33;
    add.u32 %r33, %r33, %r17;
    add.u32 %r33, %r33, %r17;
    mul.lo.u32 %r33, %r33, 4;
    add.u32 %r34, %r32, %r33;
    // shared weight base after the padded 1200-float input halo: dyn_smem + 4800
    add.u32 %r63, %r32, 4800;
    // ---------- setup cooperative load slots for a 10x10x10 halo --------
    // round 0: li = tid
    mov.u32 %r20, %r16;
    rem.u32 %r21, %r20, 10;
    div.u32 %r22, %r20, 10;
    rem.u32 %r23, %r22, 10;
    div.u32 %r24, %r22, 10;
    add.s32 %r25, %r15, %r21;
    sub.s32 %r25, %r25, 2;              // gx
    add.s32 %r26, %r14, %r23;
    sub.s32 %r26, %r26, 2;              // gy
    add.s32 %r27, %r13, %r24;
    sub.s32 %r27, %r27, 2;              // gz
    mul.lo.u32 %r54, %r27, %r28;
    mad.lo.u32 %r54, %r26, %r10, %r54;
    add.u32 %r54, %r54, %r25;
    mul.lo.u32 %r57, %r24, 120;
    mad.lo.u32 %r57, %r23, 12, %r57;
    add.u32 %r57, %r57, %r21;
    mul.lo.u32 %r57, %r57, 4;
    add.u32 %r57, %r32, %r57;
    setp.lt.s32 %p1, %r25, 0;
    setp.ge.s32 %p2, %r25, %r10;
    or.pred %p1, %p1, %p2;
    setp.lt.s32 %p2, %r26, 0;
    or.pred %p1, %p1, %p2;
    setp.ge.s32 %p2, %r26, %r10;
    or.pred %p1, %p1, %p2;
    setp.lt.s32 %p2, %r27, 0;
    or.pred %p1, %p1, %p2;
    setp.ge.s32 %p2, %r27, %r10;
    or.pred %p1, %p1, %p2;
    selp.u32 %r60, 0, 1, %p1;           // 1 = in bounds, 0 = halo
    mov.f32 %f3, 0f00000000;
    @%p1 st.shared.f32 [%r57], %f3;
    // round 1: li = tid + 256
    add.u32 %r20, %r16, 256;
    rem.u32 %r21, %r20, 10;
    div.u32 %r22, %r20, 10;
    rem.u32 %r23, %r22, 10;
    div.u32 %r24, %r22, 10;
    add.s32 %r25, %r15, %r21;
    sub.s32 %r25, %r25, 2;
    add.s32 %r26, %r14, %r23;
    sub.s32 %r26, %r26, 2;
    add.s32 %r27, %r13, %r24;
    sub.s32 %r27, %r27, 2;
    mul.lo.u32 %r55, %r27, %r28;
    mad.lo.u32 %r55, %r26, %r10, %r55;
    add.u32 %r55, %r55, %r25;
    mul.lo.u32 %r58, %r24, 120;
    mad.lo.u32 %r58, %r23, 12, %r58;
    add.u32 %r58, %r58, %r21;
    mul.lo.u32 %r58, %r58, 4;
    add.u32 %r58, %r32, %r58;
    setp.lt.s32 %p1, %r25, 0;
    setp.ge.s32 %p2, %r25, %r10;
    or.pred %p1, %p1, %p2;
    setp.lt.s32 %p2, %r26, 0;
    or.pred %p1, %p1, %p2;
    setp.ge.s32 %p2, %r26, %r10;
    or.pred %p1, %p1, %p2;
    setp.lt.s32 %p2, %r27, 0;
    or.pred %p1, %p1, %p2;
    setp.ge.s32 %p2, %r27, %r10;
    or.pred %p1, %p1, %p2;
    selp.u32 %r61, 0, 1, %p1;
    @%p1 st.shared.f32 [%r58], %f3;
    // round 2: li = tid + 512
    add.u32 %r20, %r16, 512;
    rem.u32 %r21, %r20, 10;
    div.u32 %r22, %r20, 10;
    rem.u32 %r23, %r22, 10;
    div.u32 %r24, %r22, 10;
    add.s32 %r25, %r15, %r21;
    sub.s32 %r25, %r25, 2;
    add.s32 %r26, %r14, %r23;
    sub.s32 %r26, %r26, 2;
    add.s32 %r27, %r13, %r24;
    sub.s32 %r27, %r27, 2;
    mul.lo.u32 %r56, %r27, %r28;
    mad.lo.u32 %r56, %r26, %r10, %r56;
    add.u32 %r56, %r56, %r25;
    mul.lo.u32 %r59, %r24, 120;
    mad.lo.u32 %r59, %r23, 12, %r59;
    add.u32 %r59, %r59, %r21;
    mul.lo.u32 %r59, %r59, 4;
    add.u32 %r59, %r32, %r59;
    setp.lt.s32 %p1, %r25, 0;
    setp.ge.s32 %p2, %r25, %r10;
    or.pred %p1, %p1, %p2;
    setp.lt.s32 %p2, %r26, 0;
    or.pred %p1, %p1, %p2;
    setp.ge.s32 %p2, %r26, %r10;
    or.pred %p1, %p1, %p2;
    setp.lt.s32 %p2, %r27, 0;
    or.pred %p1, %p1, %p2;
    setp.ge.s32 %p2, %r27, %r10;
    or.pred %p1, %p1, %p2;
    selp.u32 %r62, 0, 1, %p1;
    @%p1 st.shared.f32 [%r59], %f3;
    // round 3: li = tid + 768, only tid < 232
    mov.u32 %r42, 0;
    setp.lt.u32 %p3, %r16, 232;
    @!%p3 bra L_SETUP_DONE;
    add.u32 %r20, %r16, 768;
    rem.u32 %r21, %r20, 10;
    div.u32 %r22, %r20, 10;
    rem.u32 %r23, %r22, 10;
    div.u32 %r24, %r22, 10;
    add.s32 %r25, %r15, %r21;
    sub.s32 %r25, %r25, 2;
    add.s32 %r26, %r14, %r23;
    sub.s32 %r26, %r26, 2;
    add.s32 %r27, %r13, %r24;
    sub.s32 %r27, %r27, 2;
    mul.lo.u32 %r39, %r27, %r28;
    mad.lo.u32 %r39, %r26, %r10, %r39;
    add.u32 %r39, %r39, %r25;
    mul.lo.u32 %r41, %r24, 120;
    mad.lo.u32 %r41, %r23, 12, %r41;
    add.u32 %r41, %r41, %r21;
    mul.lo.u32 %r41, %r41, 4;
    add.u32 %r41, %r32, %r41;
    setp.lt.s32 %p1, %r25, 0;
    setp.ge.s32 %p2, %r25, %r10;
    or.pred %p1, %p1, %p2;
    setp.lt.s32 %p2, %r26, 0;
    or.pred %p1, %p1, %p2;
    setp.ge.s32 %p2, %r26, %r10;
    or.pred %p1, %p1, %p2;
    setp.lt.s32 %p2, %r27, 0;
    or.pred %p1, %p1, %p2;
    setp.ge.s32 %p2, %r27, %r10;
    or.pred %p1, %p1, %p2;
    selp.u32 %r42, 0, 1, %p1;
    @%p1 st.shared.f32 [%r41], %f3;
L_SETUP_DONE:
    mov.f32 %f0, 0f00000000;            // first output, oc0
    mov.f32 %f8, 0f00000000;            // first output, oc1
    mov.f32 %f9, 0f00000000;            // first output, oc2
    mov.f32 %f10, 0f00000000;           // first output, oc3
    mov.f32 %f16, 0f00000000;           // first output, oc4
    mov.f32 %f17, 0f00000000;           // first output, oc5
    mov.f32 %f18, 0f00000000;           // first output, oc6
    mov.f32 %f19, 0f00000000;           // first output, oc7
    mov.f32 %f11, 0f00000000;           // second output, oc0
    mov.f32 %f12, 0f00000000;           // second output, oc1
    mov.f32 %f13, 0f00000000;           // second output, oc2
    mov.f32 %f14, 0f00000000;           // second output, oc3
    mov.f32 %f20, 0f00000000;           // second output, oc4
    mov.f32 %f21, 0f00000000;           // second output, oc5
    mov.f32 %f22, 0f00000000;           // second output, oc6
    mov.f32 %f23, 0f00000000;           // second output, oc7
    mov.u32 %r35, 0;                    // ic loop counter
L_IC_LOOP:
    setp.ge.u32 %p0, %r35, %r8;
    @%p0 bra L_IC_DONE;
    // ---- stage current input channel halo into shared memory ----
    setp.eq.u32 %p1, %r60, 0;
    @%p1 bra L_SKIP0;
    mul.wide.u32 %rd5, %r54, 4;
    add.u64 %rd5, %rd3, %rd5;
    ld.global.nc.f32 %f3, [%rd5];
    st.shared.f32 [%r57], %f3;
L_SKIP0:
    setp.eq.u32 %p1, %r61, 0;
    @%p1 bra L_SKIP1;
    mul.wide.u32 %rd5, %r55, 4;
    add.u64 %rd5, %rd3, %rd5;
    ld.global.nc.f32 %f3, [%rd5];
    st.shared.f32 [%r58], %f3;
L_SKIP1:
    setp.eq.u32 %p1, %r62, 0;
    @%p1 bra L_SKIP2;
    mul.wide.u32 %rd5, %r56, 4;
    add.u64 %rd5, %rd3, %rd5;
    ld.global.nc.f32 %f3, [%rd5];
    st.shared.f32 [%r59], %f3;
L_SKIP2:
    setp.eq.u32 %p1, %r42, 0;
    @%p1 bra L_LOAD_DONE;
    mul.wide.u32 %rd5, %r39, 4;
    add.u64 %rd5, %rd3, %rd5;
    ld.global.nc.f32 %f3, [%rd5];
    st.shared.f32 [%r41], %f3;
L_LOAD_DONE:
    // ---- stage the 8x27 (oc0..oc0+7, ic) weights transposed [tap][oc] ----
    setp.lt.u32 %p4, %r16, 216;
    @!%p4 bra L_W_DONE;
    and.b32 %r50, %r16, 7;              // j = tid % 8 (oc lane)
    shr.u32 %r51, %r16, 3;              // t = tid / 8 (tap index)
    mul.lo.u32 %r52, %r50, 27;
    add.u32 %r52, %r52, %r51;           // weight element j*27 + t
    mul.wide.u32 %rd5, %r52, 4;
    add.u64 %rd5, %rd4, %rd5;
    ld.global.nc.f32 %f3, [%rd5];
    shl.b32 %r53, %r16, 2;              // smem slot (t*8 + j)*4 == tid*4
    add.u32 %r53, %r63, %r53;
    st.shared.f32 [%r53], %f3;
L_W_DONE:
    bar.sync 0;
    // ---- 27-tap unrolled pass: two v2 activation loads feed three taps x 8 output channels ----
    ld.shared.v2.f32 {%f1,%f2}, [%r34+1056];
    ld.shared.v2.f32 {%f3,%f15}, [%r34+1064];
    ld.shared.v4.f32 {%f4,%f5,%f6,%f7}, [%r63];
    ld.shared.v4.f32 {%f24,%f25,%f26,%f27}, [%r63+16];
    fma.rn.f32 %f0, %f3, %f4, %f0;
    fma.rn.f32 %f8, %f3, %f5, %f8;
    fma.rn.f32 %f9, %f3, %f6, %f9;
    fma.rn.f32 %f10, %f3, %f7, %f10;
