    fma.rn.f32 %f18, %f3, %f26, %f18;
    fma.rn.f32 %f19, %f3, %f27, %f19;
    fma.rn.f32 %f11, %f15, %f4, %f11;
    fma.rn.f32 %f12, %f15, %f5, %f12;
    fma.rn.f32 %f13, %f15, %f6, %f13;
    fma.rn.f32 %f14, %f15, %f7, %f14;
    fma.rn.f32 %f20, %f15, %f24, %f20;
    fma.rn.f32 %f21, %f15, %f25, %f21;
    fma.rn.f32 %f22, %f15, %f26, %f22;
    fma.rn.f32 %f23, %f15, %f27, %f23;
    ld.shared.v4.f32 {%f4,%f5,%f6,%f7}, [%r63+32];
    ld.shared.v4.f32 {%f24,%f25,%f26,%f27}, [%r63+48];
    fma.rn.f32 %f0, %f2, %f4, %f0;
    fma.rn.f32 %f8, %f2, %f5, %f8;
    fma.rn.f32 %f9, %f2, %f6, %f9;
    fma.rn.f32 %f10, %f2, %f7, %f10;
    fma.rn.f32 %f16, %f2, %f24, %f16;
    fma.rn.f32 %f17, %f2, %f25, %f17;
    fma.rn.f32 %f18, %f2, %f26, %f18;
    fma.rn.f32 %f19, %f2, %f27, %f19;
    fma.rn.f32 %f11, %f3, %f4, %f11;
    fma.rn.f32 %f12, %f3, %f5, %f12;
    fma.rn.f32 %f13, %f3, %f6, %f13;
    fma.rn.f32 %f14, %f3, %f7, %f14;
    fma.rn.f32 %f20, %f3, %f24, %f20;
    fma.rn.f32 %f21, %f3, %f25, %f21;
    fma.rn.f32 %f22, %f3, %f26, %f22;
    fma.rn.f32 %f23, %f3, %f27, %f23;
    ld.shared.v4.f32 {%f4,%f5,%f6,%f7}, [%r63+64];
    ld.shared.v4.f32 {%f24,%f25,%f26,%f27}, [%r63+80];
    fma.rn.f32 %f0, %f1, %f4, %f0;
    fma.rn.f32 %f8, %f1, %f5, %f8;
    fma.rn.f32 %f9, %f1, %f6, %f9;
